<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Par\Domain\ParRequest;
use Civi\Lughauth\Features\OAuth\Par\Domain\Exception\ParException;
use Civi\Lughauth\Features\OAuth\Par\Domain\Gateway\ParRequestGateway;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\PushAuthorizationRequest\PushAuthorizationParams;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\PushAuthorizationRequest\PushAuthorizationResult;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\PushAuthorizationRequest\PushAuthorizationUsecase;
use Civi\Lughauth\Features\OAuth\Par\Application\Usecase\ResolveParRequest\ResolveParRequestUsecase;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;

final class ParUnitTest extends TestCase
{
    // --- ParRequest ---

    public function test_par_request_stores_fields(): void
    {
        $expires = new DateTimeImmutable('+60 seconds');
        $r = new ParRequest('urn:test', 'tenant', 'client', ['key' => 'val'], $expires);

        $this->assertSame('urn:test', $r->requestUri);
        $this->assertSame('tenant', $r->tenant);
        $this->assertSame('client', $r->clientId);
        $this->assertSame(['key' => 'val'], $r->params);
        $this->assertNull($r->usedAt);
    }

    public function test_par_request_create_generates_urn_uri(): void
    {
        $r = ParRequest::create('tenant', 'client', ['response_type' => 'code']);

        $this->assertStringStartsWith('urn:ietf:params:oauth:request_uri:', $r->requestUri);
        $this->assertSame('tenant', $r->tenant);
        $this->assertSame('client', $r->clientId);
    }

    public function test_par_request_is_not_expired_when_future(): void
    {
        $r = new ParRequest('urn:test', 't', 'c', [], new DateTimeImmutable('+60 seconds'));
        $this->assertFalse($r->isExpired());
    }

    public function test_par_request_is_expired_when_past(): void
    {
        $r = new ParRequest('urn:test', 't', 'c', [], new DateTimeImmutable('-1 second'));
        $this->assertTrue($r->isExpired());
    }

    public function test_par_request_is_used_when_used_at_not_null(): void
    {
        $r = new ParRequest('urn:test', 't', 'c', [], new DateTimeImmutable('+60 seconds'), new DateTimeImmutable());
        $this->assertTrue($r->isUsed());
    }

    public function test_par_request_is_not_used_when_used_at_null(): void
    {
        $r = new ParRequest('urn:test', 't', 'c', [], new DateTimeImmutable('+60 seconds'), null);
        $this->assertFalse($r->isUsed());
    }

    // --- ParException ---

    public function test_exception_invalid_client(): void
    {
        $ex = ParException::invalidClient();
        $this->assertSame('invalid_client', $ex->error());
        $this->assertSame(401, $ex->statusCode());
    }

    public function test_exception_invalid_request_with_detail(): void
    {
        $ex = ParException::invalidRequest('response_type is required');
        $this->assertSame('invalid_request', $ex->error());
        $this->assertSame(400, $ex->statusCode());
        $this->assertStringContainsString('response_type is required', $ex->getMessage());
    }

    public function test_exception_invalid_request_uri(): void
    {
        $ex = ParException::invalidRequestUri();
        $this->assertSame('invalid_request_uri', $ex->error());
    }

    // --- PushAuthorizationParams / PushAuthorizationResult ---

    public function test_push_params_stores_fields(): void
    {
        $p = new PushAuthorizationParams('t', 'c', 'secret', ['response_type' => 'code']);
        $this->assertSame('t', $p->tenant);
        $this->assertSame('c', $p->clientId);
        $this->assertSame('secret', $p->clientSecret);
        $this->assertSame(['response_type' => 'code'], $p->authParams);
    }

    public function test_push_result_stores_fields(): void
    {
        $r = new PushAuthorizationResult('urn:test', 60);
        $this->assertSame('urn:test', $r->requestUri);
        $this->assertSame(60, $r->expiresIn);
    }

    // --- PushAuthorizationUsecase ---

    public function test_push_throws_invalid_client_when_not_found(): void
    {
        $this->expectException(ParException::class);

        $clients = $this->makeClientStore(null);
        $gateway = $this->makeParGateway();
        $usecase = new PushAuthorizationUsecase($clients, $gateway);

        $usecase->push(new PushAuthorizationParams('t', 'c', 'bad', [
            'response_type' => 'code',
            'redirect_uri' => 'https://app/cb',
            'client_id' => 'c',
        ]));
    }

    public function test_push_throws_invalid_request_when_response_type_missing(): void
    {
        $this->expectException(ParException::class);

        $client = new ClientData('c', ['authorization_code'], false);
        $clients = $this->makeClientStore($client);
        $gateway = $this->makeParGateway();
        $usecase = new PushAuthorizationUsecase($clients, $gateway);

        try {
            $usecase->push(new PushAuthorizationParams('t', 'c', 'secret', [
                'redirect_uri' => 'https://app/cb',
                'client_id' => 'c',
            ]));
        } catch (ParException $e) {
            $this->assertSame('invalid_request', $e->error());
            throw $e;
        }
    }

    public function test_push_stores_request_and_returns_result(): void
    {
        $stored = null;
        $client = new ClientData('c', ['authorization_code'], false);
        $clients = $this->makeClientStore($client);
        $gateway = $this->makeParGateway(onStore: function (ParRequest $r) use (&$stored) {
            $stored = $r;
        });
        $usecase = new PushAuthorizationUsecase($clients, $gateway);

        $result = $usecase->push(new PushAuthorizationParams('tenant', 'c', 'secret', [
            'response_type' => 'code',
            'redirect_uri' => 'https://app/cb',
            'client_id' => 'c',
        ]));

        $this->assertNotNull($stored);
        $this->assertStringStartsWith('urn:ietf:params:oauth:request_uri:', $result->requestUri);
        $this->assertSame(60, $result->expiresIn);
    }

    // --- ResolveParRequestUsecase ---

    public function test_resolve_throws_when_not_found(): void
    {
        $this->expectException(ParException::class);
        $gateway = $this->makeParGateway(byUri: null);
        $usecase = new ResolveParRequestUsecase($gateway);
        $usecase->resolve('urn:missing', 'tenant');
    }

    public function test_resolve_throws_when_already_used(): void
    {
        $this->expectException(ParException::class);
        $used = new ParRequest('urn:test', 'tenant', 'c', [], new DateTimeImmutable('+60 seconds'), new DateTimeImmutable());
        $gateway = $this->makeParGateway(byUri: $used);
        $usecase = new ResolveParRequestUsecase($gateway);
        try {
            $usecase->resolve('urn:test', 'tenant');
        } catch (ParException $e) {
            $this->assertSame('invalid_request_uri', $e->error());
            throw $e;
        }
    }

    public function test_resolve_throws_when_expired(): void
    {
        $this->expectException(ParException::class);
        $expired = new ParRequest('urn:test', 'tenant', 'c', [], new DateTimeImmutable('-1 second'));
        $gateway = $this->makeParGateway(byUri: $expired);
        $usecase = new ResolveParRequestUsecase($gateway);
        try {
            $usecase->resolve('urn:test', 'tenant');
        } catch (ParException $e) {
            $this->assertSame('invalid_request_uri', $e->error());
            throw $e;
        }
    }

    public function test_resolve_marks_used_and_returns_request(): void
    {
        $markedUri = null;
        $r = new ParRequest('urn:test', 'tenant', 'c', ['a' => 'b'], new DateTimeImmutable('+60 seconds'));
        $gateway = $this->makeParGateway(
            byUri: $r,
            onMarkUsed: function (string $uri) use (&$markedUri) {
                $markedUri = $uri;
            }
        );
        $usecase = new ResolveParRequestUsecase($gateway);

        $result = $usecase->resolve('urn:test', 'tenant');

        $this->assertSame($r, $result);
        $this->assertSame('urn:test', $markedUri);
    }

    // --- helpers ---

    private function makeClientStore(?ClientData $client): ClientStoreGateway
    {
        return new class ($client) implements ClientStoreGateway {
            public function __construct(private ?ClientData $client)
            {
            }
            public function clientData(string $clientId, string $clientSecret): ?ClientData
            {
                return $this->client;
            }
            public function findEnabledClient(string $clientId): ?ClientData
            {
                return null;
            }
            public function preValidatedClient(string $clientId): ?ClientData
            {
                return null;
            }
            public function publicClientData(string $id, string $tenant, string $redirectUrl, string $scope): ?ClientData
            {
                return null;
            }
            public function defaultRedirectUri(string $clientId): ?string
            {
                return null;
            }
        };
    }

    private function makeParGateway(?ParRequest $byUri = null, ?callable $onStore = null, ?callable $onMarkUsed = null): ParRequestGateway
    {
        return new class ($byUri, $onStore, $onMarkUsed) implements ParRequestGateway {
            public function __construct(private ?ParRequest $byUri, private $onStore, private $onMarkUsed)
            {
            }
            public function store(ParRequest $r): void
            {
                if ($this->onStore) {
                    ($this->onStore)($r);
                }
            }
            public function findByUri(string $requestUri, string $tenant): ?ParRequest
            {
                return $this->byUri;
            }
            public function markUsed(string $requestUri, string $tenant): void
            {
                if ($this->onMarkUsed) {
                    ($this->onMarkUsed)($requestUri, $tenant);
                }
            }
        };
    }
}
